class Solution:
    def cheapestFare(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        d = [inf] * n; d[src] = 0
        for _ in range(k + 1):
            nd = d[:]
            for a, b, w in flights:
                if d[a] + w < nd[b]: nd[b] = d[a] + w
            d = nd
        return -1 if d[dst] == inf else d[dst]

