function cheapestFare(n, flights, src, dst, k) {
  const g = Array.from({length: n}, () => []); for (const [a, b, w] of flights) g[a].push([b, w]);
  const best = Array.from({length: n}, () => new Array(k + 2).fill(Infinity));
  best[src][0] = 0; let frontier = [[src, 0]];
  for (let step = 1; step <= k + 1; step++) {
    const nf = new Map();
    for (const [v, c] of frontier) for (const [u, w] of g[v]) { const nc = c + w; if (!nf.has(u) || nf.get(u) > nc) nf.set(u, nc); }
    frontier = [...nf.entries()]; for (const [u, c] of frontier) best[u][step] = c;
  }
  const m = Math.min(...best[dst]); return m === Infinity ? -1 : m;
}
